// downPacket converts a packet of v2225 whose layout v2193 changed to the packet
// of v2193 of its ID, false for a packet of another ID.
func downPacket(pk proto.Packet) (proto.Packet, bool) {
	switch pk := pk.(type) {
	case *v2225.StartGamePacket:
		return downStartGamePacket(pk), true
	case *v2225.AddPlayerPacket:
		return downAddPlayerPacket(pk), true
	case *v2225.AddActorPacket:
		return downAddActorPacket(pk), true
	case *v2225.InventoryTransactionPacket:
		return downInventoryTransactionPacket(pk), true
	case *v2225.AnimatePacket:
		return downAnimatePacket(pk), true
	case *v2225.LevelChunkPacket:
		return downLevelChunkPacket(pk), true
	case *v2225.PlayerListPacket:
		return downPlayerListPacket(pk), true
	case *v2225.PlayerSkinPacket:
		return downPlayerSkinPacket(pk), true
	case *v2225.EducationSettingsPacket:
		return downEducationSettingsPacket(pk), true
	case *v2225.PlayerAuthInputPacket:
		return downPlayerAuthInputPacket(pk), true
	case *v2225.ItemStackRequestPacket:
		return downItemStackRequestPacket(pk), true
	case *v2225.ClientBoundDebugRendererPacket:
		return downClientBoundDebugRendererPacket(pk), true
	case *v2225.DimensionDataPacket:
		return downDimensionDataPacket(pk), true
	case *v2225.ServerBoundDiagnosticsPacket:
		return downServerBoundDiagnosticsPacket(pk), true
	case *v2225.ClientBoundAttributeLayerSyncPacket:
		return downClientBoundAttributeLayerSyncPacket(pk), true
	case *v2225.ClientboundUpdateSoundDataPacket:
		return downClientboundUpdateSoundDataPacket(pk), true
	}
	return nil, false
}

